(()=>{const priceMap={'1 Month':'€19','3 Months':'€29','6 Months':'€39','12 Months':'€65','24 Months':'€99'};document.querySelectorAll('.plan').forEach(card=>{card.hidden=false;const name=card.querySelector('h3')?.textContent,price=priceMap[name];if(price)card.querySelector('.price').innerHTML=`${price} <span>/ ${name.toLowerCase()}</span>`;if(name==='24 Months'){card.classList.add('hot');if(!card.querySelector('.plan-badge')){const badge=document.createElement('span');badge.className='eyebrow plan-badge';badge.textContent='Best long-term value';card.prepend(badge)}}})})();
